# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">EDEBİYAT METİNLERİNDE SORU EDATLARI VE KLASİK ESERLER</text>\n  <rect x="35" y="55" width="305" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="187" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Metin Çözümleme Soru Edatları</text>\n  <text x="55" y="108" font-size="12" fill="#334155">• مَنْ (Men): Kim? (Kişi ve yazar sorar)</text>\n  <text x="55" y="132" font-size="12" fill="#334155">• مَاذَا (Mâzâ): Ne? (Konu ve eylem sorar)</text>\n  <text x="55" y="156" font-size="12" fill="#334155">• مَتَى (Metâ) / أَيْنَ (Eyne): Ne zaman? / Nerede?</text>\n  <text x="55" y="180" font-size="12" fill="#334155">• لِمَاذَا (Limâzâ): Niçin? (Sebep sorar)</text>\n  <text x="55" y="204" font-size="12" fill="#334155">• كَيْفَ (Keyfe) / هَلْ (Hel): Nasıl? / Mı-Mi?</text>\n  <rect x="360" y="55" width="305" height="185" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="512" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Arap ve Doğu Edebiyatı Klasikleri</text>\n  <text x="380" y="112" font-size="12" font-weight="bold" fill="#854d0e">• أَلْفُ لَيْلَةٍ وَلَيْلَةٍ (Elf Leyle ve Leyle)</text>\n  <text x="395" y="132" font-size="11" fill="#475569">Binbir Gece Masalları (Dünya klasiği hikâyeler)</text>\n  <text x="380" y="160" font-size="12" font-weight="bold" fill="#854d0e">• نَوَادِرُ جُحَا (Nevâdiru Cuhâ)</text>\n  <text x="395" y="180" font-size="11" fill="#475569">Cuha / Nasreddin Hoca nükteli fıkraları</text>\n  <text x="380" y="208" font-size="12" font-weight="bold" fill="#854d0e">• مَعْرِضُ الْكِتَابِ (Ma\'ridu\'l-Kitâb)</text>\n  <text x="395" y="226" font-size="11" fill="#475569">Kitap Fuarı ve kültür etkinlikleri</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">OKUMA TERCİHLERİ VE GÜNLÜK İLETİŞİM KALIPLARI</text>\n  <rect x="35" y="55" width="315" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="192" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Edebî Tercih Cümleleri (التَّفْضِيلُ)</text>\n  <text x="55" y="110" font-size="12" fill="#334155">• أُحِبُّ الرِّوَايَاتِ التَّارِيخِيَّةَ</text>\n  <text x="65" y="128" font-size="11" fill="#475569">(Tarihî romanları severim.)</text>\n  <text x="55" y="154" font-size="12" fill="#334155">• أُحِبُّ الْكُتُبَ الدِّينِيَّةَ وَالْعِلْمِيَّةَ</text>\n  <text x="65" y="172" font-size="11" fill="#475569">(Dinî ve bilimsel eserleri severim.)</text>\n  <text x="55" y="198" font-size="12" fill="#334155">• أُفَضِّلُ قِرَاءَةَ الشِّعْرِ وَالْقِصَّةِ</text>\n  <text x="65" y="216" font-size="11" fill="#475569">(Şiir ve öykü okumayı tercih ederim.)</text>\n  <rect x="365" y="55" width="300" height="185" rx="8" fill="#fdf2f8" stroke="#ec4899"/>\n  <text x="515" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Temel Kalıp İfadeler (التَّعْبِيرَاتُ)</text>\n  <text x="385" y="110" font-size="12" fill="#334155">• هَيَّا بِنَا : Haydi gidelim / başlayalım!</text>\n  <text x="385" y="140" font-size="12" fill="#334155">• كُلُّ شَيْءٍ عَلَى مَا يُرَامُ : Her şey yolunda.</text>\n  <text x="385" y="170" font-size="12" fill="#334155">• سَلَامَتُكَ : Geçmiş olsun.</text>\n  <text x="385" y="200" font-size="12" fill="#334155">• كُلُّ عَامٍ وَأَنْتُمْ بِخَيْرٍ : Bayramınız /</text>\n  <text x="395" y="218" font-size="11" fill="#475569">yeni yılınız hayırlı olsun.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">OLAY SIRALAMA BAĞLAÇLARI VE İSİM / FİİL CÜMLESİ</text>\n  <rect x="35" y="55" width="290" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="180" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Ardışıklık ve Sıralama (التَّرْتِيبُ)</text>\n  <text x="55" y="112" font-size="12" fill="#334155">• وَ (Ve): Ve (Birliktelik bildirir)</text>\n  <text x="55" y="140" font-size="12" fill="#334155">• ثُمَّ (Sümme): Sonra (Araya zaman girer)</text>\n  <text x="55" y="168" font-size="12" fill="#334155">• قَبْلَ (Kable): Önce (قَبْلَ الدَّرْسِ: Dersten önce)</text>\n  <text x="55" y="196" font-size="12" fill="#334155">• بَعْدَ (Ba\'de): Sonra (بَعْدَ الْقِرَاءَةِ: Okumadan sonra)</text>\n  <rect x="345" y="55" width="320" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="505" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">İsim ve Fiil Cümlesi Karşılaştırması</text>\n  <text x="365" y="110" font-size="12" font-weight="bold" fill="#166534">İsim Cümlesi (İsimle başlar - Betimleme):</text>\n  <text x="365" y="130" font-size="11.5" fill="#334155">الصُّنْدُوقُ فِي زَاوِيَةِ الْغُرْفَةِ (Sandık odanın köşesindedir)</text>\n  <text x="365" y="150" font-size="11.5" fill="#334155">الرِّوَايَةُ مُمْتِعَةٌ (Roman sürükleyicidir)</text>\n  <text x="365" y="180" font-size="12" font-weight="bold" fill="#1d4ed8">Fiil Cümlesi (Fiille başlar - Eylem):</text>\n  <text x="365" y="200" font-size="11.5" fill="#334155">ذَهَبَ الطَّالِبُ إِلَى مَعْرِضِ الْكِتَابِ</text>\n  <text x="365" y="218" font-size="11" fill="#475569">(Öğrenci kitap fuarına gitti.)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
